<?php
require_once __DIR__.'/../../includes/layout.php'; require_role(['Admin','Teacher']); check_csrf();
if($_SERVER['REQUEST_METHOD']==='POST') { foreach(visible_students() as $student) generate_prediction((int)$student['id']); set_flash('success','Academic indicators refreshed from recorded grades and attendance.'); redirect('predictive.php'); }
$data=visible_students(); $counts=['High'=>0,'Medium'=>0,'Low'=>0]; foreach($data as $student) if($student['attendance_count']||$student['grade_count']) $counts[$student['risk_level']]++;
render_header('Academic insights'); ?>
<div class="page-title"><div><span class="eyebrow">STUDENT SUPPORT</span><h1>Academic insights</h1><p>Identify students who may benefit from additional support.</p></div><form method="post"><?= csrf_field() ?><button class="btn btn-primary">Refresh indicators</button></form></div>
<div class="alert alert-info">These are rule-based support indicators using recorded attendance and GPA (1.00 is best, 5.00 is failing). They are not AI predictions or estimates of dropout probability.</div>
<div class="row g-4"><div class="col-lg-4"><section class="panel"><h2 class="panel-title">Support priority</h2><canvas id="riskDist" height="220"></canvas><p class="small text-muted mt-3">High: attendance below 75% or GPA above 3.00. Medium: attendance below 85% or GPA above 2.50.</p></section></div><div class="col-lg-8"><section class="panel"><h2 class="panel-title">Student indicators</h2><?php if(!$data): empty_state('No assigned students'); else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Student</th><th>Attendance</th><th>GPA</th><th>Priority</th></tr></thead><tbody><?php foreach($data as $student): ?><tr><td><strong><?= e($student['full_name']) ?></strong><br><small><?= e($student['student_no']) ?></small></td><td><?= $student['attendance_count']?e($student['attendance_rate']).'%':'—' ?></td><td><?= $student['grade_count']?e($student['gpa']):'—' ?></td><td><span class="badge-soft risk-<?= e($student['risk_level']) ?>"><?= ($student['attendance_count']||$student['grade_count'])?e($student['risk_level']):'Not assessed' ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div></div><script>document.addEventListener('DOMContentLoaded',()=>makeDoughnut('riskDist',<?= json_encode(array_keys($counts)) ?>,<?= json_encode(array_values($counts)) ?>));</script>
<?php render_footer(); ?>
